ALTER TABLE workspaces ADD COLUMN IF NOT EXISTS workspace_type TEXT NOT NULL DEFAULT 'ORGANIZATION', ADD COLUMN IF NOT EXISTS slug TEXT, ADD COLUMN IF NOT EXISTS owner_user_id UUID, ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'ACTIVE', ADD COLUMN IF NOT EXISTS default_currency TEXT NOT NULL DEFAULT 'NGN', ADD COLUMN IF NOT EXISTS timezone TEXT NOT NULL DEFAULT 'UTC', ADD COLUMN IF NOT EXISTS country_code TEXT NOT NULL DEFAULT 'NG', ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), ADD COLUMN IF NOT EXISTS version INTEGER NOT NULL DEFAULT 1;
CREATE UNIQUE INDEX IF NOT EXISTS workspaces_slug_idx ON workspaces(slug) WHERE slug IS NOT NULL;
CREATE TABLE workspace_memberships (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), user_id UUID NOT NULL REFERENCES user_identities(id), membership_type TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('INVITED','ACTIVE','SUSPENDED','ENDED','REVOKED')), invited_by UUID, invited_at TIMESTAMPTZ NOT NULL, accepted_at TIMESTAMPTZ, suspended_at TIMESTAMPTZ, ended_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version INTEGER NOT NULL DEFAULT 1, UNIQUE(workspace_id,user_id));
CREATE INDEX workspace_memberships_active_idx ON workspace_memberships(user_id,workspace_id) WHERE status='ACTIVE';
ALTER TABLE organizations ADD COLUMN IF NOT EXISTS workspace_id UUID REFERENCES workspaces(id), ADD COLUMN IF NOT EXISTS legal_name TEXT, ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'ACTIVE', ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), ADD COLUMN IF NOT EXISTS version INTEGER NOT NULL DEFAULT 1;
CREATE TABLE legal_entities (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), organization_id UUID NOT NULL REFERENCES organizations(id), parent_legal_entity_id UUID REFERENCES legal_entities(id), legal_name TEXT NOT NULL, registration_number TEXT NOT NULL, tax_identifier_token TEXT, country_code TEXT NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, effective_from TIMESTAMPTZ NOT NULL, effective_to TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE organization_units (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), organization_id UUID NOT NULL REFERENCES organizations(id), legal_entity_id UUID REFERENCES legal_entities(id), parent_unit_id UUID REFERENCES organization_units(id), unit_type TEXT NOT NULL, name TEXT NOT NULL, code TEXT NOT NULL, status TEXT NOT NULL, effective_from TIMESTAMPTZ NOT NULL, effective_to TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version INTEGER NOT NULL DEFAULT 1, UNIQUE(workspace_id,organization_id,code));
CREATE TABLE workspace_invitations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id UUID NOT NULL REFERENCES workspaces(id), email TEXT NOT NULL, invited_role_reference TEXT NOT NULL, invitation_token_hash TEXT UNIQUE NOT NULL, status TEXT NOT NULL, invited_by UUID NOT NULL, expires_at TIMESTAMPTZ NOT NULL, accepted_by UUID, accepted_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
